style.css:
@-moz-document domain("youtube.com") {
/* ? Background */
  ytd-app {
    background-image: url("https://i.imgur.com/sewRYtC.jpeg") !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    font-family: "Comic Sans MS", "Noto Sans JP", cursive !important;
  }

  /* ? Transparent & glowing video cards */
  ytd-rich-grid-media,
  ytd-video-renderer,
  ytd-rich-item-renderer,
  ytd-thumbnail {
    background: rgba(255, 255, 255, 0.1) !important;
    backdrop-filter: blur(8px) !important;
    border-radius: 16px !important;
    box-shadow: 0 0 12px rgba(255, 255, 255, 0.3) !important;
    transition: transform 0.2s ease-in-out;
  }

  ytd-rich-grid-media:hover {
    transform: scale(1.03) !important;
    box-shadow: 0 0 24px rgba(255, 255, 255, 0.6) !important;
  }

  /* ? Make the header blend in softer */
  #masthead-container {
    background: rgba(255, 255, 255, 0.05) !important;
    backdrop-filter: blur(10px) !important;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.2) !important;
  }

  /* ✨ Font & color glow on titles */
  #video-title,
  h3,
  yt-formatted-string,
  a {
    color: #ffffff !important;
    text-shadow: 1px 1px 2px #ffdefa !important;
  }

  /* ? Remove harsh white page flashes */
  body {
    background-color: #000 !important;
  }

  /* Hide scrollbar (optional aesthetic) */
  ::-webkit-scrollbar {
    width: 0px !important;
    background: transparent !important;
  }
}
